  "When enabled, each user provides their own API key for this service. Keys are stored per-user and never shared.": "启用后，每位用户为此服务提供自己的 API Key。密钥按用户存储，绝不共享。",
  "You changed the upstream URL or endpoints; the OAuth app entered here was registered for the previous upstream and may not be valid. Update the client ID, or clear it to use dynamic client registration.": "您已更改上游 URL 或端点；此处输入的 OAuth 应用是为之前的上游注册的，可能无效。请更新客户端 ID，或清空它以使用动态客户端注册。",
  "Your IdP org authorization server's token endpoint. LiteLLM exchanges the user's identity assertion here for an ID-JAG assertion (RFC 8693 with requested_token_type=urn:ietf:params:oauth:token-type:id-jag).": "您的 IdP 组织授权服务器的令牌端点。LiteLLM 在此将用户身份断言交换为 ID-JAG 断言（带 requested_token_type=urn:ietf:params:oauth:token-type:id-jag 的 RFC 8693）。",
