  "Auto routers": "Auto Router",
  "Auto routers sit above your deployments and pick a model per request. They are called like any other model, so clients keep using a single model name.": "Auto Router 位于部署之上，为每个请求选择一个模型。它与其他模型一样被调用，客户端只需继续使用同一个模型名称。",
  "Add Auto Router": "添加 Auto Router",
  "Routes each request to a model by classifying its complexity. Called like any other model, so clients keep using a single model name.": "通过判定请求复杂度，将其路由到合适的模型。与普通模型一样被调用，客户端可继续使用同一个模型名称。",
  "Delete Auto Router": "删除 Auto Router",
  "Are you sure you want to delete \\\"{0}\\\"? Any client still calling this model name will start failing.": "确定要删除“{0}”吗？任何仍在调用此模型名称的客户端将开始报错。",
  "Auto router": "Auto Router",
  "No auto routers yet": "暂无 Auto Router",
  "Create an auto router to pick the right model per request instead of pinning one.": "创建一个 Auto Router，按请求选择合适的模型，而不是固定使用单一模型。",
  "An auto router picks the right model per request instead of pinning one.": "Auto Router 会按请求选择合适的模型，而不是固定使用单一模型。",
