  "Quality router": "质量路由器",
  "Legacy (uncalibrated)": "旧版（未校准）",
  "The rubric as it shipped before calibration examples, with no worked examples at all. Routers created before this setting existed use it, so their tier decisions and spend are unchanged. It over-routes ordinary engineering to the most expensive tier.": "校准示例引入前发布的评分标准，不包含任何示例。此设置出现前创建的路由器会继续使用它，因此层级判定和花费不会改变，但普通工程请求可能会被过度路由到最昂贵的层级。",
  Agentic: "智能体",
  "Anchors routine installs, builds, multi-file edits, and standard debugging at Medium, so ordinary engineering does not route to your most expensive tier. Suits agent, terminal, and coding-assistant traffic, and mixed traffic.": "将常规安装、构建、多文件编辑和标准调试定位为中等复杂度，避免普通工程请求路由到最昂贵层级。适用于 Agent、终端、编程助手及混合流量。",
  "Drops the engineering examples, for a router serving only conversational traffic that never sees those requests.": "移除工程类示例，适用于只处理对话流量且不会遇到此类请求的路由器。",
  "Basic questions, greetings, simple factual queries": "基础问题、问候语和简单事实查询",
  "Standard queries requiring some reasoning or explanation": "需要一定推理或解释的标准查询",
  "Technical, multi-part requests requiring deep knowledge": "需要深厚知识的技术性多部分请求",
  "Chain-of-thought, analysis, explicit reasoning requests": "思维链、分析和明确要求推理的请求",
  '"Hello!", "What is Python?", "Thanks!"': '“你好！”，“Python 是什么？”，“谢谢！”',
  '"Explain how REST APIs work", "Debug this error"': '“解释 REST API 的工作原理”，“调试此错误”',
  '"Design a microservices architecture", "Implement a rate limiter"': '“设计微服务架构”，“实现限流器”',
  '"Think step by step...", "Analyze the pros and cons..."': '“逐步思考……”，“分析优缺点……”',
  "Tier boundaries": "层级边界",
  "The weighted score each tier starts at. Scores run from -1 to 1, and short or conversational prompts score below 0, so a negative boundary is a valid way to lift trivial traffic into a higher tier.": "每个层级开始对应的加权分数。分数范围为 -1 到 1，简短或对话式提示词通常低于 0，因此负边界可以将简单流量提升到更高层级。",
  "Simple to Medium": "简单到中等",
  "Medium to Complex": "中等到复杂",
  "Complex to Reasoning": "复杂到推理",
  "Token thresholds": "Token 阈值",
  "Estimated prompt length, in tokens, that pushes the token count dimension to its floor or ceiling. Lengths between the two score neutral.": "预计会将 Token 数量维度推到下限或上限的提示词长度（Token 数）。两者之间的长度在该维度上得分为中性。",
  "Short below": "低于短长度",
  "Long above": "高于长长度",
  "Dimension weights": "维度权重",
  "How much each signal contributes to the score. Absolute multipliers, so the total need not be 1.00.": "各信号对分数的贡献程度。使用绝对乘数，因此总和不必为 1.00。",
